mapper.select:
SELECT 
  FROM pay24_deduct_table
 WHERE pay24_start_date = #{startDate}
   AND pay24_data_cd = #{dataCode}
 ORDER BY pay24_from_amt

mapper.delete:
DELETE FROM pay24_deduct_table
 WHERE pay24_deduct_table_id IN
#{id}

mapper.update:
UPDATE pay24_deduct_table
   SET pay24_limit_amt = #{limitAmt}
 WHERE pay24_start_date = #{startDate}
   AND pay24_data_cd = #{dataCode}
